-- Generated by tools/generateLiteracyMockV15Catalogue.mjs. Unified assessment bank for both entry points.
begin;
create temporary table literacy_mock_incoming(item jsonb not null) on commit drop;
-- Primitive dictionary transport; decode completely before immutable publication checks.
set local search_path = '';
create function pg_temp.lp_literacy_mock_unpack(node jsonb, dictionary jsonb) returns jsonb
language plpgsql immutable as $decode$
declare result jsonb; reference integer; slot integer; decoded_key text; begin
  if dictionary is null or jsonb_typeof(dictionary) <> 'array' then raise exception 'Invalid mock catalogue dictionary'; end if;
  if jsonb_typeof(node) = 'number' then
    if (node#>>'{}') !~ '^(0|[1-9][0-9]*)$' then raise exception 'Invalid mock catalogue reference'; end if;
    reference := (node#>>'{}')::integer;
    if reference >= jsonb_array_length(dictionary) then raise exception 'Missing mock catalogue reference'; end if;
    if jsonb_typeof(dictionary->reference) in ('array', 'object') then raise exception 'Nonprimitive mock catalogue reference'; end if;
    return dictionary->reference;
  end if;
  if node is null or jsonb_typeof(node) <> 'array' then raise exception 'Invalid encoded mock catalogue node'; end if;
  if node->0 = '0'::jsonb then
    select coalesce(jsonb_agg(pg_temp.lp_literacy_mock_unpack(value, dictionary) order by ordinal), '[]'::jsonb)
    into result from jsonb_array_elements(node) with ordinality as elements(value, ordinal) where ordinal > 1;
  elsif node->0 = '1'::jsonb and mod(jsonb_array_length(node), 2) = 1 then
    result := '{}'::jsonb;
    for slot in 1..jsonb_array_length(node) - 1 by 2 loop
      if jsonb_typeof(node->slot) <> 'number' or (node->>slot) !~ '^(0|[1-9][0-9]*)$'
        then raise exception 'Invalid mock catalogue key reference'; end if;
      reference := (node->>slot)::integer;
      if reference >= jsonb_array_length(dictionary) or jsonb_typeof(dictionary->reference) <> 'string'
        then raise exception 'Missing or nonstring mock catalogue key'; end if;
      decoded_key := dictionary->>reference;
      if result ? decoded_key then raise exception 'Duplicate mock catalogue key'; end if;
      result := result || jsonb_build_object(decoded_key, pg_temp.lp_literacy_mock_unpack(node->(slot + 1), dictionary));
    end loop;
  else raise exception 'Invalid encoded mock catalogue tag'; end if;
  return result; end; $decode$;
