do $$begin
 if (select count(*) from literacy_mock_incoming) <> 12639
  or (select count(distinct item->>'id') from literacy_mock_incoming) <> 12639 then
  raise exception 'Incomplete V15 scored bank or V14 prerequisite';
 end if;
 if exists(select 1 from literacy_mock_incoming incoming join public.literacy_mock_items old
  on old.id=incoming.item->>'id' and old.content_version='literacy-mock-v15'
  where old.item is distinct from incoming.item) then raise exception 'Cannot rewrite immutable V15 publication'; end if;
 if exists(select 1 from public.literacy_mock_publications where content_version='literacy-mock-v15' and item_count<>12639) then
  raise exception 'Published mock catalogue count is immutable';
 end if;
end; $$;
insert into public.literacy_mock_items(id,content_version,item)
select item->>'id','literacy-mock-v15',item from literacy_mock_incoming on conflict(id,content_version) do nothing;
insert into public.literacy_mock_publications(content_version,item_count)
values('literacy-mock-v15',12639) on conflict(content_version) do nothing;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v15')<>12639
  then raise exception 'Incomplete V15 publication'; end if;
end; $$;
notify pgrst,'reload schema';
commit;
